use std::collections::HashMap;
use std::env;
use std::ffi::OsString;
use std::fs::{self, File, OpenOptions};
use std::io::{self, Read, Write, BufRead, BufReader};
use std::path::{Path, PathBuf};
use std::process;

const VERSION: &str = "0.9.9";
const AUTHOR: &str = "Ajeet D'Souza <98ajeet@gmail.com>";
const ABOUT: &str = "A smarter cd command for your terminal";

#[derive(Debug, Clone)]
struct Entry {
    path: String,
    rank: f64,
    last_accessed: u64, // unix epoch seconds
}

fn eprintln_and_exit(msg: &str, code: i32) -> ! {
    eprintln!("{}", msg);
    process::exit(code);
}

fn get_data_dir() -> PathBuf {
    if let Ok(dir) = env::var("_ZO_DATA_DIR") {
        PathBuf::from(dir)
    } else if let Ok(xdg) = env::var("XDG_DATA_HOME") {
        PathBuf::from(xdg).join("zoxide")
    } else if let Some(home) = dirs::data_dir() {
        home.join("zoxide")
    } else {
        // fallback to HOME/.local/share
        if let Ok(home) = env::var("HOME") {
            PathBuf::from(home).join(".local").join("share").join("zoxide")
        } else {
            PathBuf::from(".").join("zoxide")
        }
    }
}

fn get_max_age() -> f64 {
    if let Ok(s) = env::var("_ZO_MAXAGE") {
        if let Ok(v) = s.parse::<f64>() {
            return v;
        }
    }
    10000.0
}

fn get_exclude_dirs() -> Vec<String> {
    let s = if let Ok(v) = env::var("_ZO_EXCLUDE_DIRS") {
        v
    } else {
        // default is $HOME
        if let Ok(home) = env::var("HOME") {
            home
        } else {
            String::new()
        }
    };
    if s.is_empty() {
        return vec![];
    }
    // split by : on unix, ; on windows
    let sep = if cfg!(windows) { ';' } else { ':' };
    s.split(sep).filter(|x| !x.is_empty()).map(|x| x.to_string()).collect()
}

fn is_excluded(path: &str, exclude_patterns: &[String]) -> bool {
    for pat in exclude_patterns {
        // glob matching, using glob crate
        // We need to match path against pattern
        if glob_match(pat, path) {
            return true;
        }
    }
    false
}

fn glob_match(pattern: &str, path: &str) -> bool {
    // Use glob crate's Pattern
    match glob::Pattern::new(pattern) {
        Ok(pat) => pat.matches(path),
        Err(_) => false,
    }
}

fn db_path() -> PathBuf {
    get_data_dir().join("db.zo")
}

fn load_db() -> Vec<Entry> {
    let path = db_path();
    if !path.exists() {
        return Vec::new();
    }
    let mut file = match File::open(&path) {
        Ok(f) => f,
        Err(_) => return Vec::new(),
    };
    let mut buf = Vec::new();
    if file.read_to_end(&mut buf).is_err() {
        return Vec::new();
    }
    if buf.len() < 12 {
        return Vec::new();
    }
    let version = u32::from_le_bytes([buf[0], buf[1], buf[2], buf[3]]);
    if version != 3 {
        return Vec::new();
    }
    let n = u64::from_le_bytes([buf[4], buf[5], buf[6], buf[7], buf[8], buf[9], buf[10], buf[11]]) as usize;
    let mut off = 12;
    let mut entries = Vec::with_capacity(n);
    for _ in 0..n {
        if off + 8 > buf.len() { break; }
        let plen = u64::from_le_bytes([buf[off],buf[off+1],buf[off+2],buf[off+3],buf[off+4],buf[off+5],buf[off+6],buf[off+7]]) as usize;
        off += 8;
        if off + plen > buf.len() { break; }
        let path_bytes = &buf[off..off+plen];
        let p = String::from_utf8_lossy(path_bytes).to_string();
        off += plen;
        if off + 8 > buf.len() { break; }
        let rank = f64::from_le_bytes([buf[off],buf[off+1],buf[off+2],buf[off+3],buf[off+4],buf[off+5],buf[off+6],buf[off+7]]);
        off += 8;
        if off + 8 > buf.len() { break; }
        let last = u64::from_le_bytes([buf[off],buf[off+1],buf[off+2],buf[off+3],buf[off+4],buf[off+5],buf[off+6],buf[off+7]]);
        off += 8;
        entries.push(Entry { path: p, rank, last_accessed: last });
    }
    entries
}

fn save_db(entries: &[Entry]) -> io::Result<()> {
    let dir = get_data_dir();
    fs::create_dir_all(&dir)?;
    let path = db_path();
    let tmp_path = dir.join("db.zo.tmp");
    let mut buf = Vec::new();
    buf.extend_from_slice(&3u32.to_le_bytes());
    buf.extend_from_slice(&(entries.len() as u64).to_le_bytes());
    for e in entries {
        let path_bytes = e.path.as_bytes();
        buf.extend_from_slice(&(path_bytes.len() as u64).to_le_bytes());
        buf.extend_from_slice(path_bytes);
        buf.extend_from_slice(&e.rank.to_le_bytes());
        buf.extend_from_slice(&e.last_accessed.to_le_bytes());
    }
    {
        let mut f = File::create(&tmp_path)?;
        f.write_all(&buf)?;
        f.sync_all()?;
    }
    fs::rename(tmp_path, path)?;
    Ok(())
}

fn now_secs() -> u64 {
    // Use system time
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs()
}

fn score(entry: &Entry, now: u64) -> f64 {
    let duration = now.saturating_sub(entry.last_accessed);
    let factor = if duration < 3600 {
        4.0
    } else if duration < 86400 {
        2.0
    } else if duration < 604800 {
        0.5
    } else {
        0.25
    };
    entry.rank * factor
}

fn add_paths(paths: Vec<String>, inc: f64) {
    let mut entries = load_db();
    let maxage = get_max_age();
    let exclude = get_exclude_dirs();
    let resolve = env::var("_ZO_RESOLVE_SYMLINKS").map(|v| v=="1").unwrap_or(false);
    let now = now_secs();
    for p in paths {
        let mut path = p;
        // Resolve symlinks if needed? For add, path is stored; if resolve, canonicalize?
        // But we need to handle relative paths: make absolute
        let pb = PathBuf::from(&path);
        let abs = if pb.is_absolute() {
            pb
        } else {
            env::current_dir().unwrap_or(PathBuf::from(".")).join(pb)
        };
        // Normalize: remove trailing slash unless root
        let mut abs_str = abs.to_string_lossy().to_string();
        // Canonicalize a bit: remove trailing slash
        if abs_str.len() > 1 && abs_str.ends_with('/') {
            abs_str.pop();
            while abs_str.len() > 1 && abs_str.ends_with('/') {
                abs_str.pop();
            }
        }
        // Resolve symlinks if _ZO_RESOLVE_SYMLINKS=1
        if resolve {
            // Use canonicalize if exists, else keep
            if let Ok(canonical) = fs::canonicalize(&abs_str) {
                abs_str = canonical.to_string_lossy().to_string();
            }
        } else {
            // Normalize by cleaning? The original may use real path? For now keep as is but clean dot components?
            // We should use lexical normalization: remove ./ and ../? For simplicity, use canonical parent if exists?
            // But we saw add with relative "a/b" became "/tmp/reltest/a/b" which is abs + not canonical beyond existence check.
            // So keep abs_str as is after making absolute.
        }
        // Check if it's a directory
        if !Path::new(&abs_str).is_dir() {
            eprintln!("zoxide: not a directory: {}", path);
            process::exit(1);
        }
        // Check exclude
        if is_excluded(&abs_str, &exclude) {
            // If excluded, don't add, but exit 0?
            // From earlier tests, add with excluded still exit 0 but doesn't add.
            // So skip adding but not error.
            continue;
        }
        // Find existing
        let mut found = false;
        for e in entries.iter_mut() {
            if e.path == abs_str {
                e.rank += inc;
                e.last_accessed = now;
                found = true;
                break;
            }
        }
        if !found {
            entries.push(Entry { path: abs_str.clone(), rank: inc, last_accessed: now });
        }
        // Check maxage overflow
        let total: f64 = entries.iter().map(|e| e.rank).sum();
        if total > maxage {
            let factor = 0.9 * maxage / total;
            for e in entries.iter_mut() {
