fn path_matches(path: &str, keywords: &[String]) -> bool {
    if keywords.is_empty() {
        return true;
    }
    let lower = path.to_lowercase();
    let kws: Vec<String> = keywords.iter().map(|k| k.to_lowercase()).collect();
    let last = &kws[kws.len()-1];
    // parent length
    let parent_len = if let Some(idx) = lower.rfind('/') {
        idx + 1
    } else {
        0
    };
    let parent = &lower[..parent_len];
    // helper to check earlier keywords
    let check_prefix = |prefix: &str| -> bool {
        let mut pos = 0;
        for kw in &kws[..kws.len()-1] {
            if let Some(idx) = prefix[pos..].find(kw.as_str()) {
                pos += idx + kw.len();
            } else {
                return false;
            }
        }
        true
    };
    if last.contains('/') {
        if last.ends_with('/') {
            if !parent.ends_with(last) {
                return false;
            }
            let start = parent_len - last.len();
            let prefix = &lower[..start];
            return check_prefix(prefix);
        } else {
            // contains slash but not trailing
            // find occurrences ending inside last component (end > parent_len)
            let mut occs = Vec::new();
            let mut start = 0;
            while let Some(idx) = lower[start..].find(last.as_str()) {
                let abs_idx = start + idx;
                let end = abs_idx + last.len();
                if end > parent_len && end <= lower.len() {
                    occs.push(abs_idx);
                }
                start = abs_idx + 1;
                if start >= lower.len() { break; }
            }
            for idx in occs {
                let prefix = &lower[..idx];
                if check_prefix(prefix) {
                    return true;
                }
            }
            return false;
        }
    } else {
        // no slash
        // find occurrences inside last component
        let last_comp_start = parent_len;
        let last_comp = &lower[last_comp_start..];
        let mut occs = Vec::new();
        let mut start = 0;
        while let Some(idx) = last_comp[start..].find(last.as_str()) {
            let abs_idx = last_comp_start + start + idx;
            occs.push(abs_idx);
            start += idx + 1;
            if start >= last_comp.len() { break; }
        }
        if occs.is_empty() {
            return false;
        }
        for idx in occs {
            let prefix = &lower[..idx];
            if check_prefix(prefix) {
                return true;
            }
        }
        return false;
    }
}

fn query(args: &[String]) {
    // parse args for query
    let mut all = false;
    let mut interactive = false;
    let mut list = false;
    let mut score = false;
    let mut exclude: Option<String> = None;
    let mut base_dir: Option<String> = None;
    let mut keywords: Vec<String> = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "--all" || a == "-a" {
            all = true;
        } else if a == "--interactive" || a == "-i" {
            interactive = true;
        } else if a == "--list" || a == "-l" {
            list = true;
        } else if a == "--score" || a == "-s" {
            score = true;
        } else if a == "--exclude" {
            if i+1 >= args.len() {
                eprintln!("error: a value is required for '--exclude <path>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                process::exit(2);
            }
            exclude = Some(args[i+1].clone());
            i+=1;
        } else if a.starts_with("--exclude=") {
            exclude = Some(a["--exclude=".len()..].to_string());
        } else if a == "--base-dir" {
            if i+1 >= args.len() {
                eprintln!("error: a value is required for '--base-dir <path>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                process::exit(2);
            }
            base_dir = Some(args[i+1].clone());
            i+=1;
        } else if a.starts_with("--base-dir=") {
            base_dir = Some(a["--base-dir=".len()..].to_string());
        } else if a == "--help" || a == "-h" {
            print_help_query();
            process::exit(0);
        } else if a == "--version" || a == "-V" {
            println!("zoxide-query {}", VERSION);
            process::exit(0);
        } else if a == "--" {
            // remaining are keywords
            for k in &args[i+1..] {
                keywords.push(k.clone());
            }
            break;
        } else if a.starts_with('-') {
            eprintln!("error: unexpected argument '{}' found", a);
            eprintln!();
            eprintln!("  tip: to pass '{}' as a value, use '-- {}'", a, a);
            eprintln!();
            eprintln!("Usage: executable query [OPTIONS] [KEYWORDS]...");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            process::exit(2);
        } else {
            keywords.push(a.clone());
        }
        i+=1;
    }
    if interactive && list {
        eprintln!("error: the argument '--interactive' cannot be used with '--list'");
        eprintln!();
        eprintln!("Usage: executable query --interactive [KEYWORDS]...");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }
    if interactive {
        // Check fzf
        let fzf_exists = which_fzf();
        if !fzf_exists {
            eprintln!("zoxide: could not find fzf, is it installed?");
            process::exit(1);
        }
        // Interactive not implemented fallback?
        // For now just do non-interactive? But we need to handle interactive selection via fzf.
        // We can attempt to run fzf if available, but for test without fzf we already exited.
        // If fzf exists, we would do interactive.
        // For now, if fzf exists, just do query and pipe to fzf? But we don't have fzf in this environment, so just exit.
        // We'll implement basic fzf invocation
        let entries = load_db();
        let now = now_secs();
        let mut candidates: Vec<(f64, String)> = Vec::new();
        for e in &entries {
            if !all && !Path::new(&e.path).exists() {
                continue;
            }
            if let Some(base) = &base_dir {
                let base_norm = if base.ends_with('/') { base.clone() } else { format!("{}/", base) };
                // base-dir check: path must be within base_dir
                // Also allow exact match?
                if !(e.path == *base || e.path.starts_with(&base_norm) || e.path.starts_with(base)) {
                    // Use simple prefix check: must be base + "/" or equal
                    let mut ok = false;
                    if e.path == *base { ok = true; }
                    else if e.path.starts_with(base) {
                        let rest = &e.path[base.len()..];
                        if rest.starts_with('/') { ok = true; }
                    }
                    if !ok { continue; }
                }
            }
            if let Some(ex) = &exclude {
                if e.path == *ex { continue; }
            }
            if !path_matches(&e.path, &keywords) {
                continue;
            }
            let s = score(e, now);
            candidates.push((s, e.path.clone()));
        }
        candidates.sort_by(|a,b| b.0.partial_cmp(&a.0).unwrap().then_with(|| a.1.cmp(&b.1)));
        // If no candidates, exit 1
        if candidates.is_empty() {
            eprintln!("zoxide: no match found");
            process::exit(1);
        }
        // Run fzf
        // Build input
        let mut input = String::new();
        for (sc, p) in &candidates {
            if score {
                input.push_str(&format!("{:>8.1} {}\n", sc, p));
            } else {
                input.push_str(&format!("{}\n", p));
            }
        }
        // Call fzf
        let fzf_opts = env::var("_ZO_FZF_OPTS").unwrap_or_default();
        let mut cmd = process::Command::new("fzf");
        if !fzf_opts.is_empty() {
            for opt in shell_split(&fzf_opts) {
                cmd.arg(opt);
            }
        }
        cmd.stdin(process::Stdio::piped());
        cmd.stdout(process::Stdio::piped());
        let mut child = match cmd.spawn() {
            Ok(c) => c,
            Err(_) => {
                eprintln!("zoxide: could not find fzf, is it installed?");
                process::exit(1);
            }
        };
        {
            let stdin = child.stdin.as_mut().unwrap();
            stdin.write_all(input.as_bytes()).unwrap();
        }
        let output = child.wait_with_output().unwrap();
        if !output.status.success() {
            process::exit(1);
        }
        let out_str = String::from_utf8_lossy(&output.stdout);
        let selected = out_str.trim();
        // If score was enabled, need to extract path
        let path = if score {
            // score + path, path is after score
            selected.split_whitespace().last().unwrap_or("").to_string()
        } else {
            selected.to_string()
        };
        if path.is_empty() {
            process::exit(1);
        }
        println!("{}", path);
        return;
    }

    let entries = load_db();
    let now = now_secs();
    let mut candidates: Vec<(f64, String)> = Vec::new();
    for e in &entries {
        if !all && !Path::new(&e.path).exists() {
            continue;
        }
        if let Some(base) = &base_dir {
            // base-dir filter
            let base_norm = if base.ends_with('/') { base.clone() } else { format!("{}/", base) };
            let mut ok = false;
            if e.path == *base { ok = true; }
            else if e.path.starts_with(&base_norm) { ok = true; }
            else if e.path.starts_with(base) {
                // ensure directory boundary
                let rest = &e.path[base.len()..];
                if rest.starts_with('/') { ok = true; }
            }
            if !ok { continue; }
        }
        if let Some(ex) = &exclude {
            if e.path == *ex { continue; }
        }
        if !path_matches(&e.path, &keywords) {
            continue;
        }
        let s = score(e, now);
        candidates.push((s, e.path.clone()));
    }
    candidates.sort_by(|a,b| b.0.partial_cmp(&a.0).unwrap().then_with(|| a.1.cmp(&b.1)));
    if candidates.is_empty() {
        if list {
            // list with no matches exits 0 with empty output
            return;
        } else {
            // check if exclude caused "you are already in the only match"
            if let Some(ex) = &exclude {
                // If there is exactly one candidate that would match without exclude, but is excluded, then error message "you are already in the only match"
                // We need to check if without exclude there would be exactly one match that is the excluded path
                let mut without_exclude = Vec::new();
                for e in &entries {
                    if !all && !Path::new(&e.path).exists() { continue; }
                    if let Some(base) = &base_dir {
                        let base_norm = if base.ends_with('/') { base.clone() } else { format!("{}/", base) };
                        let mut ok = false;
                        if e.path == *base { ok = true; }
                        else if e.path.starts_with(&base_norm) { ok = true; }
                        else if e.path.starts_with(base) {
                            let rest = &e.path[base.len()..];
                            if rest.starts_with('/') { ok = true; }
                        }
                        if !ok { continue; }
                    }
                    if !path_matches(&e.path, &keywords) { continue; }
                    without_exclude.push(e);
                }
                if without_exclude.len() == 1 && without_exclude[0].path == *ex {
                    eprintln!("zoxide: you are already in the only match");
                    process::exit(1);
                }
            }
            eprintln!("zoxide: no match found");
            process::exit(1);
        }
    }
    if list {
        for (sc, p) in candidates {
            if score {
                println!("{:>8.1} {}", sc, p);
            } else {
                println!("{}", p);
            }
        }
    } else {
        // only best
        let (sc, p) = &candidates[0];
        if score {
            println!("{:>8.1} {}", sc, p);
        } else {
            println!("{}", p);
        }
    }
}

fn which_fzf() -> bool {
    // Check if fzf is in PATH
    if let Ok(path) = env::var("PATH") {
        for dir in path.split(':') {
            let p = Path::new(dir).join("fzf");
            if p.exists() {
                return true;
            }
        }
    }
    false
}

fn shell_split(s: &str) -> Vec<String> {
    // Very simple split by whitespace, respecting quotes? For now simple
    // We'll use shlex-like? Just split whitespace
    s.split_whitespace().map(|x| x.to_string()).collect()
}

