                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    process::exit(2);
                }
            }
        } else if a == "--help" || a == "-h" {
            print_help_add();
            process::exit(0);
        } else if a == "--version" || a == "-V" {
            println!("zoxide-add {}", VERSION);
            process::exit(0);
        } else if a == "--" {
            for p in &args[i+1..] {
                paths.push(p.clone());
            }
            break;
        } else if a.starts_with('-') {
            eprintln!("error: unexpected argument '{}' found", a);
            eprintln!();
            eprintln!("  tip: to pass '{}' as a value, use '-- {}'", a, a);
            eprintln!();
            eprintln!("Usage: executable add [OPTIONS] <PATHS>...");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            process::exit(2);
        } else {
            paths.push(a.clone());
        }
        i += 1;
    }
    if paths.is_empty() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <PATHS>...");
        eprintln!();
        eprintln!("Usage: executable add <PATHS>...");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }
    let inc = score.unwrap_or(1.0);
    add_paths(paths, inc);
}

