            eprintln!("For more information, try '--help'.");
            process::exit(2);
        } else {
            paths.push(a.clone());
        }
        i+=1;
    }
    // remove expects at least one? Original allows zero? But help says [PATHS]... optional? Let's check behavior: ./executable remove without args exit 0? From earlier test, ./executable remove without args gave exit 0? Actually earlier we tested remove with no args: ./executable remove 2>&1; echo exit:$? gave? We saw remove with nonexist gave error. Without args, what does original do? Let's test: if no paths, it should probably do nothing? But help shows [PATHS]... meaning optional. We'll allow no paths to succeed.
    let mut entries = load_db();
