    // We'll try to mimic: if fzf exists, we would run fzf to select entries and open editor.
    // For now, just exit 0 if fzf exists.
    // However, without fzf we already exited 1.
    // So just exit 0.
    process::exit(0);
}

fn do_init(args: &[String]) {
    let mut cmd = "z".to_string();
    let mut hook = "pwd".to_string();
    let mut no_cmd = false;
    let mut shell: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "--no-cmd" {
            no_cmd = true;
        } else if a == "--cmd" {
            if i+1 >= args.len() {
                eprintln!("error: a value is required for '--cmd <CMD>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                process::exit(2);
            }
            cmd = args[i+1].clone();
            i+=1;
        } else if a.starts_with("--cmd=") {
            cmd = a["--cmd=".len()..].to_string();
        } else if a == "--hook" {
            if i+1 >= args.len() {
                eprintln!("error: a value is required for '--hook <HOOK>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                process::exit(2);
            }
            hook = args[i+1].clone();
            i+=1;
        } else if a.starts_with("--hook=") {
            hook = a["--hook=".len()..].to_string();
        } else if a == "--help" || a == "-h" {
            print_help_init();
            process::exit(0);
        } else if a == "--version" || a == "-V" {
            println!("zoxide-init {}", VERSION);
            process::exit(0);
        } else if a.starts_with('-') {
            eprintln!("error: unexpected argument '{}' found", a);
            eprintln!();
            eprintln!("  tip: to pass '{}' as a value, use '-- {}'", a, a);
            eprintln!();
            eprintln!("Usage: executable init [OPTIONS] <SHELL>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            process::exit(2);
        } else {
            if shell.is_some() {
                eprintln!("error: unexpected argument '{}' found", a);
                eprintln!();
                eprintln!("Usage: executable init [OPTIONS] <SHELL>");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                process::exit(2);
            }
            shell = Some(a.clone());
        }
        i+=1;
    }
    let shell = match shell {
        Some(s) => s,
        None => {
            eprintln!("error: the following required arguments were not provided:");
            eprintln!("  <SHELL>");
            eprintln!();
            eprintln!("Usage: executable init <SHELL>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            process::exit(2);
        }
    };
    let valid_shells = ["bash","elvish","fish","nushell","posix","powershell","tcsh","xonsh","zsh"];
    if !valid_shells.contains(&shell.as_str()) {
        eprintln!("error: invalid value '{}' for '<SHELL>'", shell);
        eprintln!("  [possible values: bash, elvish, fish, nushell, posix, powershell, tcsh, xonsh, zsh]");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }
    let valid_hooks = ["none","prompt","pwd"];
    if !valid_hooks.contains(&hook.as_str()) {
        eprintln!("error: invalid value '{}' for '--hook <HOOK>'", hook);
        eprintln!("  [possible values: none, prompt, pwd]");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }
    // Generate template
    let key = format!("{}_{}_{}_nocmd{}.out", shell, hook, cmd, if no_cmd {1} else {0});
    // For default cmd z with no_cmd 0, the file is like bash_pwd_z_nocmd0.out
    // But our capture used naming: {shell}_{hook}_{cmd}_nocmd{n}.out
    // For cmd=z default, that's correct.
    // For shells where cmd is z, we have file.
    // However, for generic, we need to load from embedded map.
    // Instead of using key, we will have a function that returns template string based on params.
    // We have embedded templates as match.
    let template = get_init_template(&shell, &hook, &cmd, no_cmd);
    print!("{}", template);
}

fn get_init_template(shell: &str, hook: &str, cmd: &str, no_cmd: bool) -> String {
    // Include the captured templates as raw strings
