                eprintln!();
                eprintln!("For more information, try '--help'.");
                process::exit(2);
            }
            let v = &args[i+1];
            match v.parse::<f64>() {
                Ok(f) => score = Some(f),
                Err(_) => {
                    eprintln!("error: invalid value '{}' for '--score <SCORE>': invalid float literal", v);
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    process::exit(2);
                }
            }
            i += 2;
            continue;
        } else if a.starts_with("--score=") {
