            println!("zoxide-remove {}", VERSION);
            process::exit(0);
        } else if a == "--" {
            for p in &args[i+1..] {
                paths.push(p.clone());
            }
            break;
        } else if a.starts_with('-') {
            eprintln!("error: unexpected argument '{}' found", a);
