            pb
        } else {
            env::current_dir().unwrap_or(PathBuf::from(".")).join(pb)
        };
        let mut abs_str = abs.to_string_lossy().to_string();
        if abs_str.len()>1 && abs_str.ends_with('/') {
            abs_str.pop();
            while abs_str.len()>1 && abs_str.ends_with('/') { abs_str.pop(); }
        }
        // Resolve? Probably not for remove.
        let pos = entries.iter().position(|e| e.path == abs_str);
        if let Some(idx) = pos {
            entries.remove(idx);
        } else {
            // Try also with raw p if absolute? Original remove may accept relative? We'll also try canonical?
            // For now, error
            eprintln!("zoxide: path not found in database: {}", p);
            had_error = true;
        }
    }
    if let Err(e) = save_db(&entries) {
        eprintln!("zoxide: could not save database: {}", e);
        process::exit(1);
    }
    if had_error {
        process::exit(1);
    }
}

fn do_import(args: &[String]) {
    let mut from: Option<String> = None;
    let mut merge = false;
    let mut path: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "--from" {
            if i+1 >= args.len() {
                eprintln!("error: a value is required for '--from <FROM>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                process::exit(2);
            }
            from = Some(args[i+1].clone());
            i+=2;
            continue;
        } else if a.starts_with("--from=") {
            from = Some(a["--from=".len()..].to_string());
        } else if a == "--merge" {
            merge = true;
        } else if a == "--help" || a == "-h" {
            print_help_import();
            process::exit(0);
        } else if a == "--version" || a == "-V" {
            println!("zoxide-import {}", VERSION);
            process::exit(0);
        } else if a.starts_with('-') {
            eprintln!("error: unexpected argument '{}' found", a);
            eprintln!();
            eprintln!("  tip: to pass '{}' as a value, use '-- {}'", a, a);
            eprintln!();
            eprintln!("Usage: executable import [OPTIONS] --from <FROM> <PATH>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            process::exit(2);
        } else {
            if path.is_some() {
                eprintln!("error: unexpected argument '{}' found", a);
                eprintln!();
                eprintln!("Usage: executable import [OPTIONS] --from <FROM> <PATH>");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                process::exit(2);
            }
            path = Some(a.clone());
        }
        i+=1;
    }
    if from.is_none() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  --from <FROM>");
        eprintln!();
        eprintln!("Usage: executable import [OPTIONS] --from <FROM> <PATH>");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }
    if path.is_none() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <PATH>");
        eprintln!();
        eprintln!("Usage: executable import [OPTIONS] --from <FROM> <PATH>");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }
    let from = from.unwrap();
    if from != "z" && from != "autojump" {
        eprintln!("error: invalid value '{}' for '--from <FROM>'", from);
        eprintln!("  [possible values: autojump, z]");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }
    let path = path.unwrap();
    // check file exists
    let data = match fs::read_to_string(&path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("zoxide: could not open database for importing: {}", path);
            eprintln!();
            eprintln!("Caused by:");
            eprintln!("    {} (os error {})", e, e.raw_os_error().unwrap_or(2));
            process::exit(1);
        }
    };
    let mut entries = load_db();
    if !entries.is_empty() && !merge {
        eprintln!("zoxide: current database is not empty, specify --merge to continue anyway");
        process::exit(1);
    }
    if from == "z" {
        // format: path|rank|last_accessed
        for line in data.lines() {
            if line.trim().is_empty() { continue; }
            let parts: Vec<&str> = line.split('|').collect();
            if parts.len() != 3 { continue; }
            let p = parts[0].to_string();
            let rank: f64 = parts[1].parse().unwrap_or(0.0);
            let last: u64 = parts[2].parse().unwrap_or(0);
            // Check if path exists? For import, should we store even if not exists? Original stores even if not exists? We saw mkdir before import. But if path doesn't exist, still import?
            // We'll store anyway.
            let mut found = false;
            for e in entries.iter_mut() {
                if e.path == p {
                    e.rank += rank;
                    if last > e.last_accessed {
                        e.last_accessed = last;
                    }
                    found = true;
                    break;
                }
            }
            if !found {
                entries.push(Entry { path: p, rank, last_accessed: last });
            }
        }
    } else if from == "autojump" {
        // format: rank<TAB>path
        for line in data.lines() {
            if line.trim().is_empty() { continue; }
            let parts: Vec<&str> = line.split('\t').collect();
            if parts.len() != 2 { continue; }
            let rank_raw: f64 = parts[0].parse().unwrap_or(0.0);
            let p = parts[1].to_string();
            let rank = 1.0 / (1.0 + (-rank_raw).exp()); // sigmoid
            let last = 0u64; // autojump has no timestamp?
            let mut found = false;
            for e in entries.iter_mut() {
                if e.path == p {
                    e.rank += rank;
                    found = true;
                    break;
                }
            }
            if !found {
                entries.push(Entry { path: p, rank, last_accessed: last });
            }
        }
    }
    // Check maxage after import? Should apply same overflow logic
    let maxage = get_max_age();
    let total: f64 = entries.iter().map(|e| e.rank).sum();
    if total > maxage {
        let factor = 0.9 * maxage / total;
        for e in entries.iter_mut() {
            e.rank *= factor;
        }
        entries.retain(|e| e.rank >= 1.0);
    }
    if let Err(e) = save_db(&entries) {
        eprintln!("zoxide: could not save database: {}", e);
        process::exit(1);
    }
}

fn do_edit(_args: &[String]) {
    // Check fzf
    if !which_fzf() {
        eprintln!("zoxide: could not find fzf, is it installed?");
        process::exit(1);
    }
    // Not fully implemented, but we can just exit 0? Original edit with fzf would open editor.
